'use strict';
(() => {
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const base=['127.0.0.1','localhost'].includes(location.hostname)?location.origin:'http://127.0.0.1:4173';
 let token=null,tab='problem',lastLesson='';
 const initial=()=>({method:'GET',path:'',contentType:'',body:''});
 function read(code){try{return {...initial(),...JSON.parse(code)};}catch{return initial();}}
 async function execute(code,lessonId,submit){
  try{
   if(!token){const r=await fetch(base+'/api/practice-api/status'),data=await r.json();if(!r.ok)throw new Error(data.error||'Chưa kết nối được lab API.');token=data.token;}
   const response=await fetch(base+'/api/practice-api/'+(submit?'submit':'run'),{method:'POST',headers:{'Content-Type':'application/json','X-TechPath-Token':token},body:JSON.stringify({lessonId,request:read(code)})});
   const result=await response.json();if(!response.ok){if(response.status===403)token=null;throw new Error(result.error||'Chưa gửi được request.');}return result;
  }catch(error){if(error instanceof TypeError)throw new Error('Chưa kết nối được lab API trên máy. Khởi động bản local mới rồi thử lại.');throw error;}
 }
 const output=response=>response?`<div class="compiler-message"><span>HTTP ${esc(response.status)} · Response body (JSON)</span><pre>${esc(JSON.stringify(response.body,null,2))}</pre></div><details><summary>Response headers</summary><pre class="sample-code">${esc(JSON.stringify(response.headers,null,2))}</pre></details>`:'';
 function result(r){
  const judge=r.judge,passed=judge?.verdict==='pass',cases=judge?.cases||[],index=Math.max(0,cases.findIndex(c=>!c.passed));
  return `<section class="api-result" aria-live="polite" aria-label="Kết quả API"><div class="result-heading ${judge?(passed?'accepted':'failed'):!r.ok||r.response?.status>=400?'failed':'run-neutral'}"><div><span class="eyebrow">${judge?'SUBMISSION RESULT':'RUN RESULT'}</span><h2>${judge?(passed?'✓ Accepted · Đạt':'✕ Chưa đạt'):r.response?'Response · HTTP '+r.response.status:'✕ Chưa gửi được request'}</h2>${judge?`<p>${esc(judge.summary)}</p>`:''}</div><span class="result-time">${Number(r.elapsedMs)||0} ms</span></div>${r.error?`<div class="compiler-message"><span>${esc(r.error.code||'CONNECTION_ERROR')}</span><pre>${esc(r.error.message||r.error)}</pre></div>`:''}${judge?`<p class="judge-basis">Đạt ${cases.filter(c=>c.passed).length}/${cases.length} kiểm tra. Kết quả thuộc request đã nộp. Không gọi AI.</p><div class="case-layout"><nav class="case-list" aria-label="Các kiểm tra API">${cases.map((c,i)=>`<button type="button" data-api-case="${i}" class="${i===index?'active':''} ${c.passed?'case-pass':'case-fail'}" aria-pressed="${i===index}"><span>${c.passed?'✓':'✕'}</span>${esc(c.name)}</button>`).join('')}</nav><div class="case-detail">${cases.map((c,i)=>`<section data-api-case-panel="${i}" ${i!==index?'hidden':''}><h3>${esc(c.name)} · ${c.passed?'Đạt':'Chưa đạt'}</h3><div class="compiler-message"><span>Thông báo</span><pre>${esc(c.message)}</pre></div>${output(r.response)}<div class="compiler-message"><span>Response mong đợi · HTTP ${esc(judge.expectedStatus)}</span><pre>${esc(judge.expectedBody)}</pre></div></section>`).join('')}</div></div>`:output(r.response)}<p class="save-meta">API mô phỏng trong lab · mỗi lần chạy bắt đầu với dữ liệu mẫu ban đầu. ${judge?'':'Chạy thử chưa lưu lần nộp.'}</p></section>`;
 }
 function render(l,d,run,attempts,practice){
  if(!practice)return window.TechPathPython.render(l,d,null,[],false).replace('href="#lessons/python"','href="#lessons/api"').replace('Hiểu bài Python','Hiểu bài API');
  if(lastLesson!==l.id){lastLesson=l.id;tab='problem';}
  const sequence=window.TECHPATH.lessons.filter(item=>item.module==='api'),next=sequence[sequence.findIndex(item=>item.id===l.id)+1],last=attempts.slice().reverse().find(a=>a.apiJudging);
  const r=run?.result||(last?last.apiJudging:null),old=run?.code??last?.code,stale=old!==undefined&&old!==d.code,request=read(d.code);
  const nextLink=next&&r?.judge?.verdict==='pass'&&!stale?`<a class="button secondary" data-api-next href="#lesson/${next.id}">${next.apiGroup===l.apiGroup?'Bài luyện tiếp theo':'Nhóm tiếp theo: '+next.pythonGroupTitle} →</a>`:'';
  const problem=`<div class="problem-intro"><span class="eyebrow">THỰC HÀNH API · ${esc(l.pythonGroupTitle)} ${l.groupStep}/3</span><h1>${esc(l.title)}</h1><p>${esc(l.summary)}</p></div><section><h2>Yêu cầu</h2><p class="challenge-task">${esc(l.task)}.</p><h3>Response mong đợi</h3><pre class="sample-code">${esc(l.expected)}</pre></section><section><h2>Cách làm</h2><p>Chọn method và điền đường dẫn. Bài POST cần thêm Content-Type và body JSON. Chạy để xem response; Nộp bài để kiểm tra yêu cầu và lưu.</p><p>Đây là API mô phỏng, không gửi tới website ngoài hoặc thay đổi dữ liệu thật. Không cần tài khoản hay API key.</p></section>`;
  const guide=`<h2>Gợi ý từng bước</h2>${l.hints.slice(0,d.hints).map((h,i)=>`<p>${i+1}. ${esc(h)}</p>`).join('')}<button class="button secondary" data-hint ${d.hints>=3?'disabled':''}>Mở một gợi ý</button><details><summary>Lời giải tham khảo</summary>${d.solution?`<pre class="sample-code">${esc(l.solution)}</pre>`:'<p>Chỉ mở khi bạn muốn đối chiếu.</p><button class="button secondary" data-solution>Mở lời giải</button>'}</details>`;
  const submissions=`<h2>Lần nộp</h2>${attempts.filter(a=>a.apiJudging).slice().reverse().map(a=>`<details><summary>${a.apiJudging.judge.verdict==='pass'?'Đạt':'Cần sửa'} · ${esc(new Date(a.at).toLocaleString('vi-VN'))}</summary><pre class="sample-code">${esc(a.code)}</pre>${result(a.apiJudging)}</details>`).join('')||'<p>Chưa nộp bài.</p>'}`;
  return `<section class="challenge-workspace api-workspace"><header class="challenge-header"><div><a href="#lesson/${l.id}">← Lý thuyết & ví dụ</a><span class="challenge-title">${esc(l.title)}</span></div><span class="challenge-engine">API lab · Mô phỏng</span></header><div class="challenge-split"><article class="challenge-problem"><div class="challenge-tabs" role="tablist" aria-label="Thông tin bài API">${[['problem','Đề bài'],['guide','Gợi ý'],['submissions','Lần nộp']].map(([key,label])=>`<button role="tab" data-api-tab="${key}" aria-selected="${tab===key}">${label}${key==='submissions'?' · '+attempts.filter(a=>a.apiJudging).length:''}</button>`).join('')}</div><div class="challenge-document" role="tabpanel">${tab==='guide'?guide:tab==='submissions'?submissions:problem}</div></article><section class="challenge-coding"><div class="editor-heading"><label>Request Builder <span>HTTP</span></label><span>● Tự lưu trên thiết bị</span></div><div class="api-request-form"><div class="api-request-line"><label>Method<select id="api-method"><option ${request.method==='GET'?'selected':''}>GET</option><option ${request.method==='POST'?'selected':''}>POST</option></select></label><label>Đường dẫn<input id="api-path" value="${esc(request.path)}" placeholder="/hello" spellcheck="false" autocomplete="off"></label></div><details class="api-body-options" ${l.apiGroup>=4?'open':''}><summary>Body và Content-Type · dành cho bài POST</summary><label for="api-content-type">Content-Type <span class="save-meta">(dùng cho POST JSON)</span></label><input id="api-content-type" value="${esc(request.contentType)}" placeholder="application/json" autocomplete="off"><label for="api-body">Body (JSON) <span class="save-meta">· GET để trống</span></label><textarea id="api-body" aria-label="Body JSON" spellcheck="false" placeholder="Viết body khi đề yêu cầu…">${esc(request.body)}</textarea></details><textarea id="draft-code" hidden readonly>${esc(d.code)}</textarea></div><div class="challenge-toolbar"><div><button class="button ghost small" data-new-attempt>Lần thử mới</button><button class="button ghost small" data-download-code>Tải request</button></div><div><button class="button secondary" data-run-api>Chạy</button><button class="button" data-submit-api>Nộp bài</button>${nextLink}</div></div><div class="challenge-console"><div id="api-results">${stale?'<p class="stale-result">Request đã thay đổi. Kết quả bên dưới thuộc bản cũ; hãy chạy hoặc nộp lại.</p>':''}<div class="challenge-result">${r?result(r):'<div class="empty-console"><h3>Sẵn sàng gửi request</h3><p>Chạy để xem response; Nộp bài để kiểm tra và lưu.</p></div>'}</div>${!next&&r?.judge?.verdict==='pass'&&!stale?'<p class="python-continuation">Đã xong nhóm API hiện tại. Bạn có thể ôn lại hoặc quay về phần nền tảng AI Engineer.</p>':''}</div><textarea id="draft-output" hidden readonly>${esc(d.output)}</textarea></div></section></div></section>`;
 }
 function mount(){
  const editor=document.querySelector('.api-workspace');if(!editor)return;
  const code=editor.querySelector('#draft-code'),fields=['method','path','content-type','body'];
  const serialize=()=>JSON.stringify({method:editor.querySelector('#api-method').value,path:editor.querySelector('#api-path').value,contentType:editor.querySelector('#api-content-type').value,body:editor.querySelector('#api-body').value});
  code.value=serialize();
  fields.forEach(name=>editor.querySelector('#api-'+name).addEventListener('input',()=>{code.value=serialize();code.dispatchEvent(new Event('input',{bubbles:true}));}));
  for(const name of ['path','body'])window.TechPathCompletion?.mountHistory(editor.querySelector('#api-'+name),'api:'+location.hash.split('/')[1]+':'+name);
  editor.addEventListener('click',event=>{
   const button=event.target.closest('[data-api-case]');if(!button)return;const panel=button.closest('.api-result');
   panel.querySelectorAll('[data-api-case]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});panel.querySelectorAll('[data-api-case-panel]').forEach(p=>p.hidden=p.dataset.apiCasePanel!==button.dataset.apiCase);
  });
 }
 window.TechPathApi={render,mount,run:(code,id)=>execute(code,id,false),submit:(code,id)=>execute(code,id,true),tab:value=>{if(['problem','guide','submissions'].includes(value))tab=value;}};
})();
